1	// The constructor keeps public named params (`dio`, `urlBuilder`) distinct
2	// from the private fields they initialize, so an initializing formal
3	// (which would force the external name to match) isn't a clean fit here.
4	// ignore_for_file: prefer_initializing_formals
5	import 'dart:convert';
6	
7	import 'package:dio/dio.dart';
8	import 'package:flutter/foundation.dart';
9	import 'package:fpdart/fpdart.dart';
10	
11	import '../failure/failure.dart';
12	import '../session/session_expiry_notifier.dart';
13	import 'dio_error_code.dart';
14	import 'header_interceptor.dart';
15	import 'url_builder.dart';
16	
17	/// AD-2/AD-5 — the one network façade every repository's data source calls
18	/// through. Builds the real URL via `UrlBuilder`, sends the request through
19	/// `dio` (header + retry interceptors already attached in DI), and maps
20	/// every outcome — success or failure — to `Either<Failure, T>`; no
21	/// dio/native exception ever escapes unmapped (RNF09).
22	///
23	/// Story 1.5: also the one detection point for a mid-session `AUTH_EXPIRED`
24	/// — signals [SessionExpiryNotifier] when one is seen outside
25	/// `HeaderInterceptor.anonKeyOnlyFunctions`, so the boot-time `auth-refresh`
26	/// call (Story 1.4's `restoreSession()`) never triggers it.
27	///
28	/// Tests mock this interface directly (per the architecture spine's testing
29	/// convention), not a fake transport layer underneath it.
30	class ApiClient {
31	  ApiClient({
32	    required Dio dio,
33	    required UrlBuilder urlBuilder,
34	    required SessionExpiryNotifier sessionExpiryNotifier,
35	  })  : _dio = dio,
36	        _urlBuilder = urlBuilder,
37	        _sessionExpiryNotifier = sessionExpiryNotifier;
38	
39	  final Dio _dio;
40	  final UrlBuilder _urlBuilder;
41	  final SessionExpiryNotifier _sessionExpiryNotifier;
42	
43	  Future<Either<Failure, Map<String, dynamic>>> get(
44	    String function, {
45	    List<String> pathParams = const [],
46	    Map<String, dynamic>? queryParameters,
47	  }) =>
48	      _send(
49	        () => _dio.get<Map<String, dynamic>>(
50	          _urlBuilder.build(function, pathParams),
51	          queryParameters: queryParameters,
52	        ),
53	      );
54	
55	  Future<Either<Failure, Map<String, dynamic>>> post(
56	    String function, {
57	    List<String> pathParams = const [],
58	    Object? data,
59	  }) =>
60	      _send(
61	        () => _dio.post<Map<String, dynamic>>(
62	          _urlBuilder.build(function, pathParams),
63	          data: data,
64	        ),
65	      );
66	
67	  Future<Either<Failure, Map<String, dynamic>>> patch(
68	    String function, {
69	    List<String> pathParams = const [],
70	    Object? data,
71	  }) =>
72	      _send(
73	        () => _dio.patch<Map<String, dynamic>>(
74	          _urlBuilder.build(function, pathParams),
75	          data: data,
76	        ),
77	      );
78	
79	  Future<Either<Failure, Map<String, dynamic>>> delete(
80	    String function, {
81	    List<String> pathParams = const [],
82	    Object? data,
83	  }) =>
84	      _send(
85	        () => _dio.delete<Map<String, dynamic>>(
86	          _urlBuilder.build(function, pathParams),
87	          data: data,
88	        ),
89	      );
90	
91	  /// spec-6-1 — streaming companion to [post]: sent with
92	  /// `ResponseType.stream` so the SSE response body never gets buffered
93	  /// into a single in-memory JSON blob the way [post]'s own
94	  /// `Dio.post<Map<String, dynamic>>` would. Each emitted `Right` is one
95	  /// raw, UTF-8-decoded chunk straight off the wire — SSE `event:`/`data:`
96	  /// line-splitting stays feature-local (`ChatRemoteDataSource`), this
97	  /// façade only owns the transport + error-mapping step (Boundaries:
98	  /// "ApiClient stays the one façade every datasource calls through").
99	  /// `allowMalformed: true` mirrors every other decode step in this app
100	  /// (RNF09: never throw on a malformed byte sequence) — a chunk that
101	  /// can't be exactly transcoded still degrades to the replacement
102	  /// character rather than crashing the stream.
103	  ///
104	  /// A connection that closes cleanly with no further error is simply a
105	  /// stream that ends with no further `Right`/`Left` emitted — detecting
106	  /// that as a "mid-stream drop" (no `done`/`error` SSE event ever seen)
107	  /// is the caller's job, not this method's; `ApiClient` has no notion of
108	  /// the SSE event grammar.
109	  Stream<Either<Failure, String>> postStream(
110	    String function, {
111	    List<String> pathParams = const [],
112	    Object? data,
113	  }) async* {
114	    try {
115	      final response = await _dio.post<ResponseBody>(
116	        _urlBuilder.build(function, pathParams),
117	        data: data,
118	        // `receiveTimeout: Duration.zero` overrides `BaseOptions`' own 30s
119	        // (set for every other, non-streaming call) for this one request —
120	        // dio restarts that timer on every received chunk (including the
121	        // gap before the very first one), so it fires mid-generation
122	        // whenever the RAG+LLM pipeline takes longer than 30s to flush the
123	        // next SSE event, aborting the connection client-side while the
124	        // backend keeps running and persists the full answer regardless
125	        // (bug: the aborted bubble then shows `failed` for an answer that
126	        // actually succeeded, and a later retry — finding no `serverId`,
127	        // since even `message_created` never arrived — resends as a brand
128	        // new message instead of regenerating in place). The backend's own
129	        // `AI_GENERATION_TIMEOUT` in-band `error` event (`error-taxonomy.md`,
130	        // already mapped by `_parseEvent`) is this call's real circuit
131	        // breaker for a generation that's actually stuck — no client-side
132	        // receive-gap timeout is needed on top of it here.
133	        // `persistentConnection: false` — every other call on this `Dio`
134	        // instance happily reuses a pooled keep-alive connection, but this
135	        // one follows `chat-sessions-list`/`chat-messages-list` (fired by
136	        // `ChatCubit.init()` on every Home/Chat mount) against the same
137	        // host, then sits idle while the user types. On a real network the
138	        // edge/CDN in front of the backend closes that idle pooled
139	        // connection well before the user hits send; `dart:io`'s
140	        // `HttpClient` doesn't notice until it tries to reuse it, surfacing
141	        // as a connection error with no response (`e.response == null`),
142	        // which `dioErrorCodeOf` maps to `NETWORK_OFFLINE` —
143	        // `RetryInterceptor` never retries this function (duplicate-send
144	        // guard), so it reaches here as an immediate, silent `Left` with
145	        // zero SSE bytes ever read: an empty bubble marked `failed` within
146	        // ~1-2s, indistinguishable on screen from a real network failure.
147	        // Forcing a brand-new connection for every send/retry (never
148	        // reusing the pool) removes the race entirely — reproduces
149	        // reliably on a physical device over Wi-Fi, never on
150	        // localhost/simulator (negligible latency, no real idle-close
151	        // policy) or a one-off external call (never reuses this app's own
152	        // pooled connection to begin with).
153	        options: Options(
154	          responseType: ResponseType.stream,
155	          receiveTimeout: Duration.zero,
156	          persistentConnection: false,
157	        ),
158	      );
159	      final body = response.data;
160	      if (body == null) {
161	        yield left(
162	          const Failure.malformedResponse(message: 'Empty stream body'),
163	        );
164	        return;
165	      }
166	      // `Utf8Decoder.bind` (not a per-chunk `utf8.decode`) carries any
167	      // incomplete trailing multi-byte sequence over to the next chunk —
168	      // required here since dio's own chunk boundaries split on byte
169	      // count, not on character boundaries, and this app's primary
170	      // language (pt-BR) uses multi-byte UTF-8 characters constantly.
171	      await for (final text in const Utf8Decoder(
172	        allowMalformed: true,
173	      ).bind(body.stream)) {
174	        yield right(text);
175	      }
176	    } on DioException catch (e) {
177	      // Diagnostic only (RNF09: the mapped `Failure` below is still what
178	      // actually reaches the UI) — every other failure path in this file
179	      // swallows the real exception silently, which is exactly what made
180	      // this stream's own dropped-connection failures invisible on-device
181	      // with nothing printed to the console. Kept past this specific
182	      // investigation: a silent transport failure here is always worth a
183	      // trace, the same rationale `HeaderInterceptor`'s own `debugPrint`
184	      // calls already follow.
185	      debugPrint(
186	        'ApiClient.postStream: DioException ${e.type} on '
187	        '${e.requestOptions.path} — ${e.message ?? e.error}',
188	      );
189	      yield left(await _mapStreamDioException(e));
190	    } catch (e) {
191	      debugPrint('ApiClient.postStream: unexpected error — $e');
192	      yield left(Failure.malformedResponse(message: e.toString()));
193	    }
194	  }
195	
196	  /// [postStream]'s own error-mapping step. A non-2xx response to a
197	  /// `ResponseType.stream` request is never auto-decoded into a `Map` by
198	  /// dio's default transformer (dio's own contract: "you must return the
199	  /// responseBody when Options.responseType is stream") — [e.response]'s
200	  /// `data` is still the raw, undrained [ResponseBody] at this point, so
201	  /// [_mapDioException]'s own `data is Map` check always misses it and
202	  /// would otherwise collapse every real backend error code on this one
203	  /// streaming endpoint into [Failure.malformedResponse]. Draining and
204	  /// decoding it here, once, keeps that same `{code, message}` mapping
205	  /// (`error-taxonomy.md`) correct for the stream path too, without
206	  /// changing [_mapDioException]/`dioErrorCodeOf` themselves — both are
207	  /// shared with `RetryInterceptor`, which never sees a stream response at
208	  /// all (it retries before dio's transformer runs), so widening their
209	  /// `Map`-only contract isn't needed here. Any failure to drain/decode
210	  /// (including a non-JSON body) falls back to [_mapDioException]'s own
211	  /// generic mapping unchanged.
212	  Future<Failure> _mapStreamDioException(DioException e) async {
213	    final data = e.response?.data;
214	    if (data is ResponseBody) {
215	      try {
216	        final bytes = await data.stream.expand((chunk) => chunk).toList();
217	        final decoded = jsonDecode(utf8.decode(bytes, allowMalformed: true));
218	        if (decoded is Map && decoded['code'] is String) {
219	          final message = decoded['message'];
220	          final failure = Failure.fromCode(
221	            decoded['code'] as String,
222	            (message is String ? message : null) ?? 'Unknown error',
223	          );
224	          if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
225	            _sessionExpiryNotifier.notifyExpired();
226	          }
227	          return failure;
228	        }
229	      } catch (_) {
230	        // Falls through to the generic mapping below — same "never throw"
231	        // rationale every other decode step in this file already follows.
232	      }
233	    }
234	    return _mapDioException(e);
235	  }
236	
237	  Future<Either<Failure, Map<String, dynamic>>> _send(
238	    Future<Response<Map<String, dynamic>>> Function() request,
239	  ) async {
240	    try {
241	      final response = await request();
242	      final data = response.data;
243	      if (data == null) {
244	        return left(
245	          const Failure.malformedResponse(message: 'Empty response body'),
246	        );
247	      }
248	      return right(data);
249	    } on DioException catch (e) {
250	      return left(_mapDioException(e));
251	    } catch (e) {
252	      return left(Failure.malformedResponse(message: e.toString()));
253	    }
254	  }
255	
256	  Failure _mapDioException(DioException e) {
257	    final code = dioErrorCodeOf(e);
258	    if (code == null) {
259	      // Covers a cancelled request and an HTTP response that doesn't carry
260	      // the expected `{code, message, retryable}` body — neither is one of
261	      // the 13 backend codes, so neither is retryable (dioErrorCodeOf).
262	      return Failure.malformedResponse(
263	        message: e.message ?? 'Malformed response',
264	      );
265	    }
266	    final data = e.response?.data;
267	    final message = data is Map ? data['message'] : null;
268	    final failure = Failure.fromCode(
269	      code,
270	      (message is String ? message : null) ?? e.message ?? 'Unknown error',
271	    );
272	    if (failure is AuthExpired && !_isAnonKeyOnlyCall(e)) {
273	      _sessionExpiryNotifier.notifyExpired();
274	    }
275	    return failure;
276	  }
277	
278	  /// Whether [e]'s request targeted one of the three `security: []`
279	  /// operations (signup, login, refresh) — the only calls `AUTH_EXPIRED`
280	  /// must never be treated as a mid-session expiry for, since those are the
281	  /// anon-keyed calls Story 1.4's `restoreSession()` itself makes.
282	  ///
283	  /// Mirrors `HeaderInterceptor.onRequest`'s own fail-open behavior: a
284	  /// malformed `requestOptions.path` (shouldn't happen — `UrlBuilder`
285	  /// always produces a valid URL) is treated as "not anon-key-only" rather
286	  /// than letting a `FormatException` escape this mapping step unmapped
287	  /// (RNF09).
288	  bool _isAnonKeyOnlyCall(DioException e) {
289	    String function;
290	    try {
291	      function = HeaderInterceptor.functionNameOf(e.requestOptions.path);
292	    } catch (_) {
293	      function = '';
294	    }
295	    return HeaderInterceptor.anonKeyOnlyFunctions.contains(function);
296	  }
297	}
