1	/// One parsed SSE event from `chat.messages.send`'s streaming response
2	/// (`openapi.yaml`: `message_created -> context -> token* -> done|error`,
3	/// in this order). `context` is intentionally never modeled here — the
4	/// Boundaries explicitly exclude "rendering the SSE `context` event's
5	/// retrieval/citation data"; `ChatRemoteDataSource` receives and discards
6	/// it before it would ever become one of these. `error` likewise never
7	/// becomes a member of this type — it's a terminal failure, surfaced as
8	/// `Left(Failure.fromCode(...))` by the same stream this event type flows
9	/// through (`ChatRepository.sendMessage`'s own `Stream<Either<Failure,
10	/// ChatStreamEvent>>`), never wrapped as a `Right` value.
11	///
12	/// A plain sealed class, not `freezed` (mirrors `core/resource.dart`'s own
13	/// `Resource<T>` — AD-12's prose: "Chat's state is its own sealed class,
14	/// never forced into `Resource<T>`" extends to this smaller stream-event
15	/// type too, no union/copyWith machinery needed for 3 fixed, flat shapes).
16	sealed class ChatStreamEvent {
17	  const ChatStreamEvent();
18	}
19	
20	/// Design Notes: "`message_created` carries the persisted user-message
21	/// id" — the id the backend just assigned to the user's own just-sent
22	/// message (not the AI response being generated). Unused by this story's
23	/// own `ChatCubit` (no retry-by-id feature yet, Boundaries) — modeled now
24	/// so Story 6.3's retry call has a value to key off without re-parsing the
25	/// stream.
26	class ChatMessageCreatedEvent extends ChatStreamEvent {
27	  const ChatMessageCreatedEvent(this.userMessageId);
28	
29	  final String userMessageId;
30	
31	  @override
32	  bool operator ==(Object other) =>
33	      identical(this, other) ||
34	      (other is ChatMessageCreatedEvent &&
35	          other.userMessageId == userMessageId);
36	
37	  @override
38	  int get hashCode => userMessageId.hashCode;
39	
40	  @override
41	  String toString() => 'ChatMessageCreatedEvent(userMessageId: $userMessageId)';
42	}
43	
44	/// One `token` event's `delta` — Design Notes: "this spec assumes `token`
45	/// carries a `delta` text field". `ChatCubit` appends [delta] onto the
46	/// streaming AI bubble's content on every emission.
47	class ChatTokenEvent extends ChatStreamEvent {
48	  const ChatTokenEvent(this.delta);
49	
50	  final String delta;
51	
52	  @override
53	  bool operator ==(Object other) =>
54	      identical(this, other) || (other is ChatTokenEvent && other.delta == delta);
55	
56	  @override
57	  int get hashCode => delta.hashCode;
58	
59	  @override
60	  String toString() => 'ChatTokenEvent(delta: $delta)';
61	}
62	
63	/// The stream's own successful terminator — marks the AI bubble `complete`.
64	class ChatDoneEvent extends ChatStreamEvent {
