38	/// `showGeneralDialog` on the `Navigator` *above* this screen's own widget
39	/// subtree (`expiry_overlay_host.dart`) — this screen is never popped or
40	/// rebuilt from scratch underneath it, so [_scrollController]'s position
41	/// and [cubit]'s state survive that overlay appearing with no extra code
42	/// needed here (Acceptance Criteria's third bullet).
43	class MeusRegistrosScreen extends StatefulWidget {
44	  const MeusRegistrosScreen({
45	    required this.cubit,
46	    required this.searchCubit,
47	    super.key,
48	  });
49	
50	  final MeusRegistrosCubit cubit;
51	
52	  /// spec-5-1 — the permanently-docked `EntriesSearchBar`'s own cubit, a DI
53	  /// `lazySingleton` like [cubit] (Code Map); this `StatefulWidget` never
54	  /// closes it either, same rationale [cubit]'s own doc above gives.
55	  final EntriesSearchCubit searchCubit;
