61	class _MeusRegistrosScreenState extends State<MeusRegistrosScreen> {
62	  // RNF01: no loading UI below 300ms — same threshold/`Timer` pattern as
63	  // `BootSplashScreen`.
64	  static const _skeletonThreshold = Duration(milliseconds: 300);
65	
66	  final ScrollController _scrollController = ScrollController();
67	  Timer? _skeletonTimer;
68	  bool _showSkeleton = false;
69	
70	  /// spec-5-1 — the search surface's own 300ms skeleton threshold,
71	  /// mirroring [_skeletonTimer]/[_showSkeleton] above but keyed off
72	  /// `EntriesSearchCubit`'s `ResourceLoading` rather than
73	  /// `MeusRegistrosLoading`: started fresh on every transition into
74	  /// `ResourceLoading` (`_onSearchStateChanged` below), since unlike the
75	  /// first-load timer above (started once, in [initState]) a search can
76	  /// enter/leave loading many times across one screen visit.
77	  Timer? _searchSkeletonTimer;
78	  bool _showSearchSkeleton = false;
79	
80	  /// Review fix (round 2, spec-4-4) — guards `_openDetail` against a rapid
81	  /// double-tap on a card pushing `/meus-registros/:id` twice (stacking two
82	  /// detail-route instances); cleared once the pushed route is popped, via
83	  /// `whenComplete` below.
84	  bool _navigatingToDetail = false;
85	
86	  @override
87	  void initState() {
88	    super.initState();
89	    widget.cubit.loadFirstPage();
90	    // spec-5-3 — both `cubit`/`searchCubit` are `lazySingleton`s (Code
91	    // Map): a fresh mount of this screen must reset both, not just
92	    // `cubit`'s own filters above, or a re-entered screen would carry a
93	    // stale filter selection from a previous visit into a still-active
94	    // search (Boundaries: "Re-enter screen after a prior combined
95	    // session").
96	    widget.searchCubit.updateFilters(
97	      source: null,
98	      dateFrom: null,
99	      dateTo: null,
100	    );
101	    _skeletonTimer = Timer(_skeletonThreshold, () {
102	      if (mounted) {
103	        setState(() => _showSkeleton = true);
104	      }
105	    });
106	    _scrollController.addListener(_onScroll);
107	    // Review finding: `searchCubit` is a long-lived singleton (Code Map)
108	    // that can already be `ResourceLoading` the moment this `State` is
109	    // (re)created — e.g. the user switches tabs away mid-search and back,
110	    // which tears down and rebuilds this plain `GoRoute`'s widget while the
111	    // DI-singleton cubit keeps running. `BlocConsumer`'s `listener` below
112	    // only fires on a *new* state, never for one already current at
113	    // subscription time, so without this check the search skeleton would
114	    // never arm for an in-flight search resumed this way.
115	    if (widget.searchCubit.state is ResourceLoading<List<Entry>>) {
116	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
117	        if (mounted) {
118	          setState(() => _showSearchSkeleton = true);
119	        }
120	      });
121	    }
122	  }
123	
124	  @override
125	  void dispose() {
126	    _skeletonTimer?.cancel();
127	    _searchSkeletonTimer?.cancel();
128	    _scrollController
129	      ..removeListener(_onScroll)
130	      ..dispose();
131	    super.dispose();
132	  }
133	
134	  /// `BlocConsumer<EntriesSearchCubit, ...>`'s own listener (below) — starts
135	  /// [_searchSkeletonTimer] fresh on every transition into
136	  /// `ResourceLoading`, mirroring [initState]'s one-shot [_skeletonTimer]
137	  /// but re-armed per search rather than once per screen visit; any other
138	  /// state (including a fast resolve before the 300ms threshold, RNF01)
139	  /// cancels it and resets [_showSearchSkeleton].
140	  void _onSearchStateChanged(
141	    BuildContext context,
142	    Resource<List<Entry>> state,
143	  ) {
144	    _searchSkeletonTimer?.cancel();
145	    if (state is ResourceLoading<List<Entry>>) {
146	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
147	        if (mounted) {
148	          setState(() => _showSearchSkeleton = true);
149	        }
150	      });
151	      return;
152	    }
153	    if (_showSearchSkeleton) {
154	      setState(() => _showSearchSkeleton = false);
155	    }
156	  }
157	
158	  void _openDetail(Entry entry) {
159	    if (_navigatingToDetail) {
160	      return;
161	    }
162	    _navigatingToDetail = true;
163	    context
164	        .push(
165	          '${AppRoutePaths.meusRegistros}/'
166	          '${Uri.encodeComponent(entry.id)}',
167	        )
168	        .whenComplete(() {
169	          if (mounted) {
170	            setState(() => _navigatingToDetail = false);
171	          } else {
172	            _navigatingToDetail = false;
173	          }
174	        });
175	  }
176	
177	  void _onScroll() {
178	    if (!_scrollController.hasClients) {
179	      return;
180	    }
181	    final position = _scrollController.position;
182	    // Pre-fetches a little before the exact end (reusing `spacing2xl`
183	    // purely as a scroll-distance buffer, not a new literal) for a
184	    // smoother scroll-pagination feel; `loadMore()` itself is a no-op once
185	    // there's no further page or a call is already in flight.
186	    if (position.pixels >= position.maxScrollExtent - DesignTokens.spacing2xl) {
187	      widget.cubit.loadMore();
188	    }
189	  }
190	
191	  @override
192	  Widget build(BuildContext context) {
193	    return MultiBlocProvider(
194	      providers: [
195	        BlocProvider.value(value: widget.cubit),
196	        BlocProvider.value(value: widget.searchCubit),
197	      ],
198	      child: Scaffold(
199	        backgroundColor: DesignTokens.colorSurfaceBg,
200	        body: Column(
201	          children: [
202	            const BackArrowHeader(title: 'Meus Registros'),
203	            Padding(
204	              padding: const EdgeInsets.fromLTRB(
205	                DesignTokens.spacingMd,
206	                DesignTokens.spacingMd,
207	                DesignTokens.spacingMd,
208	                0,
209	              ),
210	              // spec-5-2: `hasActiveFilters`/`onFilterTap` need the real
211	              // `MeusRegistrosCubit` — this now rebuilds on its state too,
212	              // while `EntriesSearchBar` itself stays a dumb, stateless
213	              // widget, same as before. spec-5-3 (Boundaries: "Funnel fill
214	              // ... drops its ResourceIdle gate — becomes
215	              // widget.cubit.hasActiveFilters unconditionally"): a filter
216	              // now also narrows an active search (via `searchCubit.
217	              // updateFilters()`), so the funnel reads as "filled"
218	              // whenever a filter is active, regardless of which surface
219	              // — plain timeline or search results — is currently on
220	              // screen; no `EntriesSearchCubit` rebuild needed here
221	              // anymore.
222	              child: BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
223	                builder: (context, _) => EntriesSearchBar(
224	                  onChanged: widget.searchCubit.onQueryChanged,
225	                  onFilterTap: () => EntriesFilterSheet.show(
226	                    context,
227	                    cubit: widget.cubit,
228	                    searchCubit: widget.searchCubit,
229	                  ),
230	                  hasActiveFilters: widget.cubit.hasActiveFilters,
231	                ),
232	              ),
233	            ),
234	            Expanded(
235	              child: BlocConsumer<EntriesSearchCubit, Resource<List<Entry>>>(
236	                listener: _onSearchStateChanged,
237	                builder: (context, searchState) {
238	                  // Boundaries: "an empty query reverts to the normal
239	                  // timeline" — `ResourceIdle` is the only variant that
240	                  // falls through to the pre-existing
241	                  // `MeusRegistrosCubit`-driven timeline below; every other
242	                  // variant renders the search surface instead.
243	                  if (searchState is ResourceIdle<List<Entry>>) {
244	                    return BlocBuilder<MeusRegistrosCubit, MeusRegistrosState>(
245	                      builder: (context, state) {
246	                        final timeline = switch (state) {
247	                          MeusRegistrosLoading() =>
248	                            _showSkeleton
249	                                ? const _SkeletonList()
250	                                : const SizedBox.shrink(),
251	                          MeusRegistrosEmpty() => const _EmptyState(),
252	                          MeusRegistrosError(message: final message) =>
253	                            _ErrorState(
254	                              message: message,
255	                              // Code-review fix: `retryCurrentPage()`, not
256	                              // `loadFirstPage()` — the latter resets the
257	                              // active filter selection, silently turning
258	                              // a failed *filtered* retry into a
259	                              // successful unfiltered one.
260	                              onRetry: widget.cubit.retryCurrentPage,
261	                            ),
262	                          MeusRegistrosLoaded() => _EntryList(
263	                            state: state,
264	                            scrollController: _scrollController,
265	                            onRetryLoadMore: widget.cubit.retryLoadMore,
266	                            onRetryTap: (entry) => widget.cubit.retry(entry.id),
267	                            onCardTap: _openDetail,
268	                          ),
269	                        };
270	                        // spec-5-2/5-3: the active-filter chip row renders
271	                        // here whenever a filter is active — this branch
272	                        // (plain/filtered timeline) or the search-results
273	                        // branch below, same condition either way (spec-5-3
274	                        // Boundaries: "`_ActiveFiltersRow` renders above
275	                        // `_SearchResults` too, same condition").
276	                        if (!widget.cubit.hasActiveFilters) {
277	                          return timeline;
278	                        }
279	                        return Column(
280	                          children: [
281	                            _ActiveFiltersRow(
282	                              cubit: widget.cubit,
283	                              searchCubit: widget.searchCubit,
284	                            ),
285	                            Expanded(child: timeline),
286	                          ],
287	                        );
288	                      },
289	                    );
290	                  }
291	                  final searchResults = _SearchResults(
292	                    state: searchState,
293	                    showSkeleton: _showSearchSkeleton,
294	                    onCardTap: _openDetail,
295	                  );
296	                  if (!widget.cubit.hasActiveFilters) {
297	                    return searchResults;
298	                  }
299	                  return Column(
300	                    children: [
301	                      _ActiveFiltersRow(
302	                        cubit: widget.cubit,
303	                        searchCubit: widget.searchCubit,
304	                      ),
305	                      Expanded(child: searchResults),
306	                    ],
307	                  );
308	                },
309	              ),
310	            ),
311	          ],
312	        ),
313	      ),
314	    );
315	  }
