821	String _dayLabel(DateTime date) {
822	  final now = DateTime.now();
823	  final today = DateTime(now.year, now.month, now.day);
824	  final yesterday = today.subtract(const Duration(days: 1));
825	  if (date == today) {
826	    return 'Hoje';
827	  }
828	  if (date == yesterday) {
829	    return 'Ontem';
830	  }
831	  final day = date.day.toString().padLeft(2, '0');
832	  final month = date.month.toString().padLeft(2, '0');
833	  return '$day/$month/${date.year}';
834	}
